<?php session_start();include "db.php";$msg="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$email=trim($_POST["email"]);$password=$_POST["password"];$s=$conn->prepare("SELECT id,name,department,password FROM employees WHERE email=?");$s->bind_param("s",$email);$s->execute();$e=$s->get_result()->fetch_assoc();if($e&&password_verify($password,$e["password"])){$_SESSION["employee_id"]=$e["id"];$_SESSION["employee_name"]=$e["name"];$_SESSION["department"]=$e["department"];header("Location: dashboard.php");exit;}$msg="Invalid email or password.";}?>
